//! Golden master tests for the DATES fitting stages against DATES v753.
//!
//! These feed DATES's own intermediate outputs into popmix so that each stage
//! is checked in isolation:
//! - `dates.out` (DATES LD table) -> `fit_exponential` vs `dates.flog` estimate
//! - `dates.jin` + full estimate -> `weighted_jackknife` vs `dates.jout`
//!
//! Reference data: tests/golden/dates/v753/, generated by
//! tests/golden/dates/generate_dates_reference.sh.
//!
//! Tolerances:
//! - Jackknife: DATES's printed precision (%9.3f generations).
//! - Fit: printed precision plus DATES's own optimizer tolerance. DATES stops
//!   its GSL simplex once it is within `gslprecision` = 1e-6 of r, i.e. up to
//!   1e-6 / step generations from the minimum. popmix minimises the same error
//!   to full precision. On chr20_22_q0, DATES stops at 3.164539 (prints 3.165)
//!   while the true minimum, with lower mean squared error, is 3.164450.

use popmix_core::dates::{fit_exponential, weighted_jackknife, DecayFitOptions, LdBin};
use std::fs;
use std::path::PathBuf;

const GEN_TOL: f64 = 5e-4 + 1e-9;
/// DATES dates_expfit `gslprecision`.
const DATES_GSL_PRECISION: f64 = 1e-6;
const STEP_MORGANS: f64 = 0.001;
const FIT_TOL: f64 = GEN_TOL + DATES_GSL_PRECISION / STEP_MORGANS;

fn ref_dir(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden/dates/v753")
        .join(name)
}

fn read_ld_table(name: &str) -> Vec<LdBin> {
    let text = fs::read_to_string(ref_dir(name).join("dates.out")).unwrap();
    text.lines()
        .filter(|l| !l.trim_start().starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            let f: Vec<&str> = l.split_whitespace().collect();
            let correlation: f64 = f[3].parse().unwrap();
            LdBin {
                distance_cm: f[0].parse().unwrap(),
                weighted_ld: f[1].parse().unwrap(),
                z_score: f64::NAN,
                correlation,
                regression_coef: f64::NAN,
                n_pairs: f[4].parse().unwrap(),
                std_err: f64::NAN,
            }
        })
        .collect()
}

fn read_full_estimate(name: &str) -> f64 {
    let text = fs::read_to_string(ref_dir(name).join("dates.flog")).unwrap();
    text.lines()
        .find_map(|l| l.strip_prefix("mean (generations):"))
        .map(|v| v.trim().parse().unwrap())
        .expect("no full-data estimate in dates.flog")
}

fn read_jin(name: &str) -> Vec<(f64, f64)> {
    let text = fs::read_to_string(ref_dir(name).join("dates.jin")).unwrap();
    text.lines()
        .map(|l| {
            let f: Vec<f64> = l.split_whitespace().map(|x| x.parse().unwrap()).collect();
            (f[1], f[2])
        })
        .collect()
}

fn read_jout(name: &str) -> (f64, f64) {
    let text = fs::read_to_string(ref_dir(name).join("dates.jout")).unwrap();
    let f: Vec<f64> = text
        .split_whitespace()
        .map(|x| x.parse().unwrap())
        .collect();
    (f[0], f[1])
}

fn dates_fit_options() -> DecayFitOptions {
    // dates_expfit -l 0.450 -a -s 0.001 as run by dates_wtjack
    {
        let mut o = DecayFitOptions::default();
        o.min_distance_cm = 0.45;
        o.max_distance_cm = f64::INFINITY;
        o.use_affine = true;
        o.bin_size_cm = 0.1;
        o
    }
}

const CONFIGS: &[&str] = &[
    "chr20_22_q0",
    "chr20_22_q10",
    "simulation_q0",
    "simulation_q10",
    "aadr_french_q10",
];

#[test]
fn fit_on_dates_ld_table_matches_dates_expfit() {
    for name in CONFIGS {
        let bins = read_ld_table(name);
        let expected = read_full_estimate(name);
        let fit = fit_exponential(&bins, &dates_fit_options()).unwrap();
        assert!(
            (fit.decay_rate - expected).abs() <= FIT_TOL,
            "{name}: popmix fit {:.6} != DATES {expected:.3}",
            fit.decay_rate
        );
    }
}

#[test]
fn weighted_jackknife_on_dates_inputs_matches_dowtjack() {
    for name in CONFIGS {
        let (expected_est, expected_se) = read_jout(name);
        let full = read_full_estimate(name);
        let estimates = read_jin(name);
        let (est, se) = weighted_jackknife(full, &estimates).unwrap();
        assert!(
            (est - expected_est).abs() <= GEN_TOL,
            "{name}: jackknife estimate {est:.6} != DATES {expected_est:.3}"
        );
        assert!(
            (se - expected_se).abs() <= GEN_TOL,
            "{name}: jackknife SE {se:.6} != DATES {expected_se:.3}"
        );
    }
}
